  // 转换所有 var 声明
  root.find(j.VariableDeclaration, {
    kind: 'var'
  }).forEach(path => {
    const decl = path.node;
    let shouldUseLet = false;
    for (const declarator of decl.declarations) {
      if (declarator.id.type === 'Identifier' && reassignedVariables.has(declarator.id.name)) {
